-- 976: Reaction injection molding calculator, version 2 -- the fill time (part volume over the staged machine injection rate).
--
-- GENERATED by scripts/generate-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/calculators/plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- The reaction injection cycle time (migration 975) was the machine dry cycle plus the material cure time: the staged machine injection rate
-- (rates.injectionRateMm3PerS) was not used, so a larger part filled in no time. The approved fill time is the total shot volume (mm3) over the
-- injection rate (mm3/s), in seconds (formula registry F-19, ASSUMED: the reference states the rate but no RIM fill formula). The calculator is
-- replaced under version 2 (a calculator in use is not edited in place under its version); the others are unchanged.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Reaction Injection Molding - Cycle Time
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Reaction Injection Molding - Cycle Time$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description, version)
    VALUES (NULL, $q$Reaction Injection Molding - Cycle Time$q$, 'process', 'single', false, true, true, $q$RIM cycle = machine dry cycle + fill + cure. Dry cycle = the machine's mold open/close with no material (staged as press_cycle_time_s). Fill Time = Total Shot Volume / Machine Injection Rate (formula registry F-19, ASSUMED: the staged rate over the shot volume is the approved simplification; the reference states no RIM fill formula), with Total Shot Volume = Part Volume x Cavities per Mold in mm3 and the rate in mm3/s, so the result is in seconds. Cure Time = the material's cure or reaction time. Cycle Time = (Dry cycle + Fill + Cure) / Cavities per Mold, per part; the RIM engine prices one part per press cycle (1 cavity). Not modelled, because the reference has no volume or formula: runner and sprue volume, mix-head purge, viscosity, flow resistance, the injection profile, and part handling. A missing or invalid part volume or injection rate makes the cycle a named gap, never a default.$q$, 2)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$RIM cycle = machine dry cycle + fill + cure. Dry cycle = the machine's mold open/close with no material (staged as press_cycle_time_s). Fill Time = Total Shot Volume / Machine Injection Rate (formula registry F-19, ASSUMED: the staged rate over the shot volume is the approved simplification; the reference states no RIM fill formula), with Total Shot Volume = Part Volume x Cavities per Mold in mm3 and the rate in mm3/s, so the result is in seconds. Cure Time = the material's cure or reaction time. Cycle Time = (Dry cycle + Fill + Cure) / Cavities per Mold, per part; the RIM engine prices one part per press cycle (1 cavity). Not modelled, because the reference has no volume or formula: runner and sprue volume, mix-head purge, viscosity, flow resistance, the injection profile, and part handling. A missing or invalid part volume or injection rate makes the cycle a named gap, never a default.$q$, version = 2, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Machine Dry Cycle Time$q$, $q$Machine Dry Cycle Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Part Volume$q$, $q$Part Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cavities per Mold$q$, $q$Cavities per Mold$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Machine Injection Rate$q$, $q$Machine Injection Rate (mm³/s)$q$, $q$number$q$, $q$mm³/s$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Material Cure Time$q$, $q$Material Cure Time (min)$q$, $q$number$q$, $q$min$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Total Shot Volume$q$, $q$Total Shot Volume (mm³)$q$, $q$calculated$q$, $q$mm³$q$, NULL, NULL, NULL, $q${Part Volume} * {Cavities per Mold}$q$, 6, false),
    (v_id, $q$Fill Time$q$, $q$Fill Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Total Shot Volume} / {Machine Injection Rate}$q$, 7, false),
    (v_id, $q$Cure Time$q$, $q$Cure Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Material Cure Time} * 60$q$, 8, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Machine Dry Cycle Time} + {Fill Time} + {Cure Time}) / {Cavities per Mold}$q$, 9, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Reaction Injection Molding - Cycle Time$q$
  WHERE process_group = $q$Plastic Molding$q$ AND operation IN ($q$Reaction Injection Molding$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Reaction Injection Molding - Cycle Time$q$, 9, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Plastic Molding$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 976: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
